  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S0]))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S0;S1;S0])) 8 10.
Definition ch_iarm0_1_0RB1LD_0RC0LA_1LB1RD_1LA1RB : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 5 0);RB (SWin 5)].
