Definition iarm_0RB1LD_0RC0LA_1LB1RD_1LA1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | 0, 1 => iarm0_1_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | 1, 0 => iarm1_0_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | 1, 1 => iarm1_1_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | 2, 0 => iarm2_0_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | 2, 1 => iarm2_1_0RB1LD_0RC0LA_1LB1RD_1LA1RB
  | _, _ => iarm0_0_0RB1LD_0RC0LA_1LB1RD_1LA1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

