Lemma iarm_rhs_0RB1LD_0RC0LA_1LB1RD_1LA1RB : forall d r,
  d < fm_b FAM - 1 -> r < 1 + 1 ->
  lr_rhs (iarm_0RB1LD_0RC0LA_1LB1RD_1LA1RB d r)
