Local Notation lad := lad_0RB1LD_0RC1RA_1LD1RB_1LA0LA.

Definition rules_0RB1LD_0RC1RA_1LD1RB_1LA0LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1LD_0RC1RA_1LD1RB_1LA0LA.

Lemma ladder_ok_0RB1LD_0RC1RA_1LD1RB_1LA0LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LD_0RC1RA_1LD1RB_1LA0LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LD_0RC1RA_1LD1RB_1LA0LA. Qed.

