  d < fm_b FAM - 1 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_0RB1RB_1RC0RD_1RD1LC_0LC1RA d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
