    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB1RB_1RC0RD_1RD1LC_0LC1RA | exact ok_iarm0_1_0RB1RB_1RC0RD_1RD1LC_0LC1RA]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

