    the machine itself. *)
Theorem nqhtr_0RB1RB_1RC0RD_1RD1LC_0LC1RA : NeverQuasiHaltsTr tm_0RB1RB_1RC0RD_1RD1LC_0LC1RA.
Proof.
  apply (boardph_neverqhtr tm_0RB1RB_1RC0RD_1RD1LC_0LC1RA pins_0RB1RB_1RC0RD_1RD1LC_0LC1RA FAM 1
                           iarm_0RB1RB_1RC0RD_1RD1LC_0LC1RA 1 1
