                           [1;1;0;1] 0 46).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
