    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1RB_1RC0RD_1RD1LC_0LC1RA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_0RB1RB_1RC0RD_1RD1LC_0LC1RA.
  - lia.
  - exact iarm_sound_0RB1RB_1RC0RD_1RD1LC_0LC1RA.
  - exact iarm_lhs_0RB1RB_1RC0RD_1RD1LC_0LC1RA.
