  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | 0, 1 => iarm0_1_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | 1, 0 => iarm1_0_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | 1, 1 => iarm1_1_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | 2, 0 => iarm2_0_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | 2, 1 => iarm2_1_1RB0LC_1LA1RD_0RD1LC_1RA0LC
  | _, _ => iarm0_0_1RB0LC_1LA1RD_0RD1LC_1RA0LC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

